[{"role": "system", "content": "You turn a plain-English description of a small situation into the represented structure of a governed simulation. Return exactly one JSON object and no prose or markdown. You are describing what exists and what actors may attempt, not what happens: do not describe consequences or rules, beyond the resources and laws the contract asks for. Follow the contract exactly; the example shows the format."}, {"role": "user", "content": "{
  "description": "I, Pencil: a pencil supply chain that keeps running. Loggers cut cedar in Oregon, a mill saws it into slats, graphite is mined in Sri Lanka and mixed with clay into leads, a factory in Pennsylvania glues leads into slats, paints them and adds erasers and brass ferrules, packs them into boxes, and trucks deliver the boxes to shops across the country, which sell them to customers.",
  "world_kind": "ongoing",
  "world_kind_rule": "World kind: keeps running. Nothing is ever finally done: work keeps arriving, or people keep living. Represent the state that lets work recur (for example an order's stage that can return to waiting, a plant's thirst counter, a count of waiting items) so the world can keep generating things to do. If it is about people living rather than working, give them needs or resources that change over time (hunger, energy, supplies, growth) as component fields, and several actions to look after them.",
  "world_size_rule": "A whole working system, typically 10 to 40 entities with at most 12 that can act, up to 10 components and 3 to 12 actions. Model it as a chain or web of specialists: several actors, each with their own role who can only do their own step (for a supply chain: raw-material producers, processors, makers of parts, assembly, transport, shops, customers), with intermediate goods passed between them as counted stock (integer quantity fields), so goods flow from one specialist to the next. If the description is about people living rather than producing, model several residents with their own needs and stocks and the resources they depend on, as counted quantities that can be produced, traded or consumed.",
  "contract": {
    "schema_version": "world-substrate-authoring-bundle/v0",
    "world": "{id (lowercase-slug), label, summary (one sentence), location (slug), content_version: 1}",
    "components": "[{name (python identifier), fields: [{name, type, default}]}]",
    "field_types": [
      "boolean",
      "entity_ref",
      "entity_ref_or_null",
      "integer",
      "number",
      "string",
      "string_list"
    ],
    "entities": "[{id (lowercase-slug), label, categories: [nonempty strings], components: {component: {every declared field}}, optional portable: bool, optional owner_ref: 'actor:<id>'|'place:<id>'|'entity:<id>'|'unowned', optional location: <id of the place entity it starts in>}] (owner_ref: use 'actor:<id>' when the owner is a person or business that acts; 'entity:<id>' only for a thing held inside another thing)",
    "actions": "[{kind (lowercase-slug), description, fields: [{name, type in string|integer|number|boolean|entity_ref}]}]",
    "reserved_action_field_names": [
      "actor",
      "kind",
      "base_revision",
      "controller"
    ],
    "presentation": "{assets: {asset_id: {kind: 'emoji', value}}, category_assets: {category: asset_id}, station_roles: {category: one of source|workstation|surface|goal}} (station_roles may be {})",
    "resources": "Optional top-level list of the things this world keeps count of that must never appear or vanish except in the ways its laws allow: [{resource_id (lowercase-slug), says (one plain sentence), kept_in: [{component, field}] naming every integer or number field that holds an amount of it}]. Money, stock of goods and stored materials are typical; feelings and scores are not.",
    "laws": "Optional top-level list of what must stay true about those resources, in this world's own terms. Two shapes. A total law: {law_id (lowercase-slug), says, resource, may_change_by: [action kinds, or 'process:<name>' for something the world does by itself]} means the resource's world total changes only through those; every other move only moves it between holders. List every move that makes the resource AND every move that uses it up: logs are made by cutting and used up by sawing them into slats, so a logs law lists both cut-cedar and saw-slats; a pencils law lists the move that makes pencils and the move that packs them into boxes or a customer uses them. If the world itself adds or removes some each round (trees regrow, bread goes stale), list it as 'process:<a short slug>'; the rules writer will give that process exactly this id. A move you leave out will be refused whenever it changes the total. A pairing law: {law_id, says, move: action kind, gives: {resource, from, to}, pays: {resource, from, to}} means that move always hands one thing over in return for another, where from and to are 'actor' or one of that action's entity_ref field names and whoever gives is whoever is paid (a sale: gives pencils shop->customer, pays money customer->shop). Use [] for both when nothing in the description is kept count of.",
    "not_modeled": "Top-level list of short plain-English strings naming every part of the description you could NOT represent with this format. Almost everything can be: money, prices, revenue, wages, feelings and distances are number fields; places are entities; packaging and small materials are entities or counted stock; delivery and travel times and deadlines are round counts. List only what truly cannot be (dice-roll chance, real clock time). Use [] when everything was represented.",
    "rules": [
      "Every entity component object must list exactly the component's declared fields, with values of the declared type.",
      "entity_ref values must name an entity id that exists in this bundle.",
      "An action that passes something to, or takes something from, another entity (hand over, deliver, carry to, supply, sell to, buy from) must have an entity_ref field naming that other entity (for example 'to', 'source' or 'customer'; field names are Python identifiers, so never 'from'); rules can only change the actor and the entities its fields name.",
      "When goods move between two entities and neither is the actor (a shopkeeper selling the shop's pencils to a customer, a carrier moving stock from the factory to the shop), the action needs an entity_ref field for each of them (for example 'shop' and 'customer', or 'source' and 'to').",
      "Rules change fixed, named quantities and cannot choose which one from a text field, so when different goods move, declare one action per kind of goods (carry-logs, carry-boards), never one carry-goods action with a field naming the goods.",
      "When the description names separate places (rooms, buildings, fields, towns), make each place an entity with category 'place', set every other entity's location to the place it starts in, and give the actors a move action with an entity_ref field 'to' naming the destination place and an entity_ref field 'way' naming what they go through. Represent what lies between two places (a door, a corridor, a wall, a river) as an entity whose component has entity_ref fields naming both places and a boolean saying whether it can be passed (a brick wall: false; an open door: true).",
      "Labels and descriptions are plain English a visitor would use (\"Ava\", \"watering can\"), never internal jargon.",
      "Size: follow world_size_rule.",
      "At least one entity is an actor that can act (give it a component such as worker/person and a clear category).",
      "Every action must be something an actor in this world could plausibly do repeatedly until the situation resolves.",
      "Represent the state the actions change (e.g. stage, count, location) as component fields with typed defaults.",
      "Represent money and value the description mentions or implies (any selling, buying, paying, wages or prices): a number field for each actor's or business's cash, and a price field on what is sold; a sale or purchase action moves the goods one way and the money the other. Represent feelings or relationships (mood, trust, hunger) as number fields when they change what people do.",
      "Every material a step uses must come from somewhere in the world: an actor who makes, mines or supplies it (a clay pit, a paint supplier) or a starting stock large enough for many rounds; never leave an input that nobody makes and nobody holds.",
      "Every step that turns things into something else needs a field for what it makes (packing pencils needs a packed_pencils count, and the next move carries packed pencils), and every move that answers a waiting need (serving an order, treating a patient) needs a field naming where that need is counted, so the move can lower it.",
      "Wherever one actor's output is another actor's input, declare an action that moves it from the one to the other (deliver, sell to, buy from), with entity_ref fields naming both, so goods can travel the whole chain; give every actor that buys a starting cash amount large enough for several purchases.",
      "When the actors hold cash, goods change hands by purchase: for each good one actor needs from another, declare a buy move the receiver starts (buy graphite from the miner) with entity_ref fields for the buyer and seller and a quantity, which moves the goods to the buyer and the seller's price for the order to the seller (rules cannot multiply, so a price is per order), and refuses when the buyer cannot pay or the seller has too few. A hand-over between actors in different places must not require them to be together: it is an order sent from afar, and the goods arrive by a delivery that counts down rounds.",
      "Represent anything that takes several rounds (a delivery on the road, a shipment, a journey, a deadline) as an integer field counting the rounds left, set by the action that starts it, so a rule process can count it down each round and finish it at zero; a longer distance is a larger starting count.",
      "Represent packaging, containers and small materials the description names as their own entities or counted stock rather than dropping them.",
      "Besides their job steps, give the actors at least one ordinary physical move that can upset the things around them, whenever the world has loose objects (stacks, cups, trays, lamps, crates): knocking over, dropping, pushing, pouring or breaking, each with an entity_ref field naming the thing it acts on. Represent where things rest and what state they are in as fields (an entity_ref 'on' or 'under', booleans such as upright, wet, broken, lit), so a rule can make one change set off another at once (a tipped cup wets what is under it).",
      "For each such move, represent what it would set off, not only the move itself: give fragile things a broken boolean, containers a full or spilled boolean, and set each loose object's 'on' to the thing it starts on (a table, a laptop, the floor), so that a fall or spill has something to break or wet.",
      "Follow world_kind_rule: a task world must be able to finish (represented state from which 'done' can be read); ongoing and open worlds must have state that keeps changing."
    ]
  },
  "example_bundle": {
    "schema_version": "world-substrate-authoring-bundle/v0",
    "world": {
      "id": "orchard",
      "label": "Orchard",
      "summary": "One worker can eventually pick ripe fruit from a represented tree.",
      "location": "orchard",
      "content_version": 1
    },
    "components": [
      {
        "name": "worker",
        "fields": [
          {
            "name": "stamina",
            "type": "integer",
            "default": 10
          }
        ]
      },
      {
        "name": "fruit",
        "fields": [
          {
            "name": "stage",
            "type": "string",
            "default": "ripe"
          },
          {
            "name": "tree_id",
            "type": "entity_ref",
            "default": "tree-1"
          }
        ]
      }
    ],
    "entities": [
      {
        "id": "ava",
        "label": "Ava",
        "categories": [
          "worker"
        ],
        "components": {
          "worker": {
            "stamina": 10
          }
        }
      },
      {
        "id": "tree-1",
        "label": "Apple tree",
        "categories": [
          "tree"
        ],
        "components": {}
      },
      {
        "id": "apple-1",
        "label": "Apple",
        "categories": [
          "fruit"
        ],
        "portable": true,
        "owner_ref": "place:orchard",
        "components": {
          "fruit": {
            "stage": "ripe",
            "tree_id": "tree-1"
          }
        }
      }
    ],
    "actions": [
      {
        "kind": "pick",
        "description": "Pick one represented fruit.",
        "fields": [
          {
            "name": "fruit",
            "type": "entity_ref"
          }
        ]
      }
    ],
    "presentation": {
      "assets": {
        "worker": {
          "kind": "emoji",
          "value": "\ud83e\uddd1\u200d\ud83c\udf3e"
        },
        "fruit": {
          "kind": "emoji",
          "value": "\ud83c\udf4e"
        }
      },
      "category_assets": {
        "worker": "worker",
        "fruit": "fruit"
      },
      "station_roles": {
        "tree": "source"
      }
    }
  }
}"}]

