    }
   ]
  },
  {
   "resource_id": "graphite",
   "says": "Graphite is counted in stock at each holder.",
   "kept_in": [
    {
     "component": "stock",
     "field": "graphite"
    }
   ]
  },
  {
   "resource_id": "clay",
   "says": "Clay is counted in stock at each holder.",
   "kept_in": [
    {
     "component": "stock",
     "field": "clay"
    }
   ]
  },
  {
   "resource_id": "leads",
   "says": "Pencil leads are counted in stock at each holder.",
   "kept_in": [
    {
     "component": "stock",
     "field": "leads"
    }
   ]
  },
  {
