{"event_id":"r2-e00002","round":2,"by":"graphite-miners","move":"mine-graphite","changed":"entities.graphite-miners.components.stock.graphite: 2 -> 3","said":"I can produce graphite, which the lead works needs to make leads."}
{"event_id":"r2-e00004","round":2,"by":"leadworks","move":"buy-graphite","changed":"entities.graphite-miners.components.business.cash: 1000 -> 1010; entities.graphite-miners.components.stock.graphite: 3 -> 2; entities.leadworks.components.business.cash: 1000 -> 990; entities.leadworks.components.stock.graphite: 0 -> 1","said":"Graphite is the missing material I can currently obtain, and I have enough cash to buy it."}
